class SnowBackground extends StatelessWidget {
  final Widget child;
  const SnowBackground({super.key, required this.child});

  @override
  Widget build(BuildContext context) {
    return Stack(
      fit: StackFit.expand,
      children: [
        const DecoratedBox(
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [Color(0xFFEAF8FD), Color(0xFFD8F0FA)],
            ),
          ),
        ),
        CustomPaint(painter: SnowPainter()),
        child,
      ],
    );
  }
}

class SnowPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.white.withValues(alpha: 0.62)
      ..strokeWidth = 1.2
      ..style = PaintingStyle.stroke;
    final points = <Offset>[
      const Offset(24, 55), const Offset(105, 130),
      const Offset(245, 65), const Offset(330, 180),
      const Offset(65, 290), const Offset(190, 370),
      const Offset(300, 440), const Offset(30, 520),
      const Offset(235, 610), const Offset(350, 700),
    ];
    for (final point in points) {
      final x = point.dx % (size.width == 0 ? 1 : size.width);
      final y = point.dy % (size.height == 0 ? 1 : size.height);
      canvas.drawLine(Offset(x - 5, y), Offset(x + 5, y), paint);
      canvas.drawLine(Offset(x, y - 5), Offset(x, y + 5), paint);
      canvas.drawLine(Offset(x - 3.5, y - 3.5), Offset(x + 3.5, y + 3.5), paint);
      canvas.drawLine(Offset(x - 3.5, y + 3.5), Offset(x + 3.5, y - 3.5), paint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

