void initState() {
  super.initState();
  loadSavedCredentials();
}

Future<void> loadSavedCredentials() async {
  final savedNick = await secureStorage.read(key: 'saved_nick');
  final savedPassword = await secureStorage.read(key: 'saved_password');

  if (!mounted) return;

  if (savedNick != null && savedPassword != null) {
    setState(() {
      nickController.text = savedNick;
      passwordController.text = savedPassword;
      remember = true;
    });
  }
}

                @override
                  void dispose() {
                      nickController.dispose();
                          passwordController.dispose();
                              super.dispose();
                                }

                                  void openRooms(String nick, String? role) {
                                      Navigator.pushReplacement(
                                          context,
                                              MaterialPageRoute(
                                                    builder: (_) => RoomsPage(
                                                            nick: nick,
                                                                    role: role,
                                                                          ),
                                                                              ),
                                                                                );
                                                                                }
                                  

                                                                        Future<void> enter() async {
                                                                            if (loading) return;

                                                                                final nick = nickController.text.trim();
                                                                                    final password = passwordController.text;

                                                                                        if (nick.isEmpty || password.isEmpty) {
                                                                                              showMessage(context, 'Введите никнейм и пароль');
                                                                                                    return;
                                                                                                        }

                                                                                                            setState(() => loading = true);

                                                                                                                try {
                                                                                                                      await AuthService.login(nick, password);
                                                                                                                      if (remember) {
  await secureStorage.write(
    key: 'saved_nick',
    value: nick,
  );

  await secureStorage.write(
    key: 'saved_password',
    value: password,
  );
} else {
  await secureStorage.delete(key: 'saved_nick');
  await secureStorage.delete(key: 'saved_password');
                                                                                                                      }
                                                                                                                      final role = await AuthService.getUserRole();

                                                                                                                      if (role == 'owner') {
                                                                                                                        print('Главный администратор вошёл');
                                                                                                                        }
if (!mounted) return;

final savedRoomId = await secureStorage.read(
  key: 'last_room_id_$nick',
);

if (savedRoomId != null) {
  final savedRoom = await Supabase.instance.client
      .from('rooms')
      .select('id, name')
      .eq('id', savedRoomId)
      .maybeSingle();

  if (!mounted) return;

  if (savedRoom != null) {
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (_) => ChatPage(
          nick: nick,
          room: savedRoom['name'].toString(),
          roomId: savedRoom['id'].toString(),
        ),
      ),
    );
    return;
  }
}

openRooms(nick, role);
                                                                                                                  
} catch (e) {
  if (!mounted) return;

  showMessage(
    context,
    e.toString().replaceFirst('Exception: ', ''),
  );
} finally {
  if (mounted) setState(() => loading = false);
}
                                                                        }                                                                                                                  

