class LoginAction extends StatelessWidget {
  final String title;
  final IconData icon;
  final Color color;
  final VoidCallback onTap;
  const LoginAction({
    super.key,
    required this.title,
    required this.icon,
    required this.color,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 38, vertical: 5),
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.88),
          border: Border.all(color: color, width: 1.2),
          borderRadius: BorderRadius.circular(7),
        ),
        child: Row(
          children: [
            Icon(icon, color: color, size: 25),
            const SizedBox(width: 14),
            Text(title, style: TextStyle(color: color, fontSize: 18)),
          ],
        ),
      ),
    );
  }
}


class RoomInfo {
  final String id;
    final String name;
      final int online;

        const RoomInfo({
            required this.id,
                required this.name,
                    this.online = 0,
                      });

                        factory RoomInfo.fromMap(Map<String, dynamic> map) {
                            return RoomInfo(
                                  id: map['id'].toString(),
                                        name: map['name'].toString(),
                                            );
                                              }
                                              }

                                              class RoomsPage extends StatefulWidget {
                                                  final String nick;
                                                    final String? role;

                                                      const RoomsPage({
                                                          super.key,
                                                              required this.nick,
                                                                  this.role,
                                                                    });

                                                    @override
                                                      State<RoomsPage> createState() => _RoomsPageState();
                                                      }

                                                      class _RoomsPageState extends State<RoomsPage> {
                                                        final supabase = Supabase.instance.client;

                                                          late Future<List<RoomInfo>> roomsFuture;

                                                            @override
                                                              void initState() {
                                                                  super.initState();
                                                                      roomsFuture = loadRooms();
                                                                        }

                                                                          Future<List<RoomInfo>> loadRooms() async {
                                                                              final data = await supabase
                                                                                      .from('rooms')
                                                                                              .select('id, name')
                                                                                                      .order('created_at');

                                                                                                          return (data as List)
                                                                                                                  .map((room) => RoomInfo.fromMap(room))
                                                                                                                          .toList();
                                                                                                                            }

                                                                                                                              @override
                                                                                                                                Widget build(BuildContext context) {
                                                                                                                                    return Scaffold(
                                                                                                                                          body: SnowBackground(
                                                                                                                                                  child: SafeArea(
                                                                                                                                                            child: Column(
                                                                                                                                                                        children: [
                                                                                                                                                                                      const BlueHeader(title: 'MoChat'),
if (widget.role == 'owner')
  Container(
    width: double.infinity,
    margin: const EdgeInsets.fromLTRB(12, 8, 12, 0),
    padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 12),
    decoration: BoxDecoration(
      color: Colors.white.withValues(alpha: 0.94),
      borderRadius: BorderRadius.circular(6),
      border: Border.all(color: moBlueDark, width: 1),
    ),
    child: const Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(Icons.verified_user, color: moBlueDark, size: 18),
        SizedBox(width: 7),
        Text(
          'ГЛАВНЫЙ АДМИНИСТРАТОР',
          style: TextStyle(
            color: moBlueDark,
            fontWeight: FontWeight.bold,
            fontSize: 13,
          ),
        ),
      ],
    ),
  ),
                                                                                                                                                                                                    Expanded(
                                                                                                                                                                                                                    child: FutureBuilder<List<RoomInfo>>(
                                                                                                                                                                                                                                      future: roomsFuture,
                                                                                                                                                                                                                                                        builder: (context, snapshot) {
                                                                                                                                                                                                                                                                            if (snapshot.connectionState ==
                                                                                                                                                                                                                                                                                                    ConnectionState.waiting) {
                                                                                                                                                                                                                                                                                                                          return const Center(
                                                                                                                                                                                                                                                                                                                                                  child: CircularProgressIndicator(),
                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                if (snapshot.hasError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      return Center(
                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'Ошибка загрузки комнат: ${snapshot.error}',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final rooms = snapshot.data ?? [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (rooms.isEmpty) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return const Center(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Text('Комнат пока нет'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return ListView.separated(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.fromLTRB(12, 18, 12, 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    itemCount: rooms.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          separatorBuilder: (_, __) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          itemBuilder: (context, index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  final room = rooms[index];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return Material(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: Colors.white.withValues(alpha: 0.94),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              borderRadius: BorderRadius.circular(5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: InkWell(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    borderRadius: BorderRadius.circular(5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onTap: () async {
  await secureStorage.write(
    key: 'last_room_id_${widget.nick}',
    value: room.id,
  );

  await secureStorage.write(
    key: 'last_room_name_${widget.nick}',
    value: room.name,
  );

  if (!mounted) return;

  Navigator.push(
    context,
    MaterialPageRoute(
      builder: (_) => ChatPage(
        nick: widget.nick,
        room: room.name,
        roomId: room.id,
      ),
    ),
  );
},
