class ChatMessage {
  final String nick;
  final String message;
  final Color color;
  const ChatMessage(this.nick, this.message, this.color);
}

class ChatPage extends StatefulWidget {
  final String nick;
  final String room;
  final String roomId;

  const ChatPage({
    super.key,
    required this.nick,
    required this.room,
    required this.roomId,
  });

  @override
  State<ChatPage> createState() => _ChatPageState();
}

class _ChatPageState extends State<ChatPage> {
  final supabase = Supabase.instance.client;
  dynamic messagesChannel;
  final controller = TextEditingController();
  final scrollController = ScrollController();

  final messages = <ChatMessage>[];
  bool isLoading = true;

  @override
void initState() {
  super.initState();
  loadMessages();
  subscribeToMessages();
}

  Future<void> loadMessages() async {
    try {
      final data = await supabase
          .from('messages')
          .select('sender_id, content')
          .eq('room_id', widget.roomId)
          .order('created_at', ascending: true);

      final senderIds = data
          .map((row) => row['sender_id'] as String)
          .toSet()
          .toList();

      final names = <String, String>{};

      if (senderIds.isNotEmpty) {
        final profiles = await supabase
            .from('profiles')
            .select('id, username')
            .inFilter('id', senderIds);

        for (final profile in profiles) {
          names[profile['id'] as String] =
              profile['username'] as String? ?? 'Пользователь';
        }
      }

      final loadedMessages = <ChatMessage>[];

      for (final row in data) {
        final senderId = row['sender_id'] as String;

        loadedMessages.add(
          ChatMessage(
            names[senderId] ?? 'Пользователь',
            row['content'] as String,
            moBlueDark,
          ),
        );
      }

      if (!mounted) return;

      setState(() {
        messages
          ..clear()
          ..addAll(loadedMessages);
        isLoading = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        isLoading = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Ошибка загрузки сообщений: $e')),
      );
    }
  }
      void subscribeToMessages() {
  messagesChannel = supabase
      .channel('room_${widget.roomId}')
      .onPostgresChanges(
        event: PostgresChangeEvent.insert,
        schema: 'public',
        table: 'messages',
        filter: PostgresChangeFilter(
          type: PostgresChangeFilterType.eq,
          column: 'room_id',
          value: widget.roomId,
        ),
        callback: (payload) {
          loadMessages();
        },
      )
      .subscribe();
  }

  @override
void dispose() {
  if (messagesChannel != null) {
    supabase.removeChannel(messagesChannel);
  }

  controller.dispose();
  scrollController.dispose();
  super.dispose();
}

  

  Future<void> send() async {
    final value = controller.text.trim();
    if (value.isEmpty) return;

    final user = supabase.auth.currentUser;
    if (user == null) return;

    controller.clear();

    try {
      await supabase.from('messages').insert({
        'room_id': widget.roomId,
        'sender_id': user.id,
        'content': value,
      });

      await loadMessages();

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (scrollController.hasClients) {
          scrollController.animateTo(
            scrollController.position.maxScrollExtent,
            duration: const Duration(milliseconds: 200),
            curve: Curves.easeOut,
          );
        }
      });
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Ошибка отправки сообщения: $e')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: SnowBackground(
        child: SafeArea(
          child: Column(
            children: [
              BlueHeader(
  title: widget.room,
),
              Container(
                width: double.infinity,
                color: const Color(0xFFE3F4FA),
                padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 10),
                child: const Text(
                  'Добро пожаловать в MoChat!',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: moBlueDark,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
              Expanded(
                child: isLoading
                    ? const Center(
                        child: CircularProgressIndicator(
                          color: moBlueDark,
                        ),
                      )
                    : ListView.builder(
                        controller: scrollController,
                        padding: const EdgeInsets.all(12),
                        itemCount: messages.length,
                        itemBuilder: (context, index) {
                          final item = messages[index];
                          return Padding(
                            padding: const EdgeInsets.symmetric(vertical: 4),
                            child: RichText(
                              text: TextSpan(
                                children: [
                                  TextSpan(
                                    text: '${item.nick}: ',
                                    style: TextStyle(
                                      color: item.color,
                                      fontWeight: FontWeight.bold,
                                      fontSize: 15,
                                    ),
                                  ),
                                  TextSpan(
                                    text: item.message,
                                    style: const TextStyle(
                                      color: Colors.black87,
                                      fontSize: 15,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      ),
              ),
              Container(
                color: Colors.white.withValues(alpha: 0.94),
                padding: const EdgeInsets.fromLTRB(8, 7, 8, 5),
                child: Row(
                  children: [
                    IconButton(
  onPressed: () => showChatMenu(context, widget.nick),
  icon: const Icon(Icons.menu, color: moBlueDark),
),
                    IconButton(
                      onPressed: () => showEmojiPicker(context, (emoji) {
                        controller.text += emoji;
                        controller.selection = TextSelection.collapsed(
                          offset: controller.text.length,
                        );
                      }),
                      icon: const Icon(Icons.emoji_emotions,
                          color: moBlueDark),
                    ),
                    Expanded(
                      child: TextField(
                        controller: controller,
                        decoration: const InputDecoration(
                          hintText: 'Сообщение...',
                          isDense: true,
                          border: OutlineInputBorder(),
                        ),
                        onSubmitted: (_) => send(),
                      ),
                    ),
                    IconButton(
                      onPressed: send,
                      icon: const Icon(Icons.send, color: moGreen),
                    ),
                  ],
                ),
              ),
              Container(
                color: moBlueDark,
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    TextButton.icon(
                      onPressed: () => Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => const PeoplePage(),
                        ),
                      ),
                      icon: const Icon(Icons.people, color: Colors.white),
                      label: const Text('Люди',
                          style: TextStyle(color: Colors.white)),
                    ),
                    TextButton.icon(
                      onPressed: () => showChatMenu(context, widget.nick),
                      icon: const Icon(Icons.menu, color: Colors.white),
                      label: const Text('Меню',
                          style: TextStyle(color: Colors.white)),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

void showEmojiPicker(BuildContext context, ValueChanged<String> onSelect) {
  const emojis = ['😀', '😂', '😍', '😘', '😉', '😊', '😎', '😭', '❤️', '👍'];
  showModalBottomSheet(
    context: context,
    builder: (_) => Padding(
      padding: const EdgeInsets.all(16),
      child: Wrap(
        spacing: 12,
        runSpacing: 12,
        children: emojis
            .map((emoji) => InkWell(
                  onTap: () {
                    onSelect(emoji);
                    Navigator.pop(context);
                  },
                  child: Text(emoji, style: const TextStyle(fontSize: 30)),
                ))
            .toList(),
      ),
    ),
  );
}

void showChatMenu(BuildContext context, String nick) {
  showModalBottomSheet(
    context: context,
    useSafeArea: true,
    builder: (sheetContext) => SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.only(bottom: 12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.meeting_room),
              title: const Text('Сменить комнату'),
              onTap: () async {
                Navigator.pop(sheetContext);

                final role = await AuthService.getUserRole();

                if (!context.mounted) return;

                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => RoomsPage(
                      nick: nick,
                      role: role,
                    ),
                  ),
                );
              },
            ),
            ListTile(
              leading: const Icon(Icons.store),
              title: const Text('Чат-портал'),
              onTap: () {
                Navigator.pop(sheetContext);
                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => const PortalPage(),
                  ),
                );
              },
            ),
            ListTile(
              leading: const Icon(Icons.person),
              title: const Text('Моя анкета'),
              onTap: () {
                Navigator.pop(sheetContext);
                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => const ProfilePage(),
                  ),
                );
              },
            ),
          ],
        ),
      ),
    ),
  );
}

