                    _ProfileAction(
                        icon: Icons.photo_library, title: 'Фотографии'),
                    _ProfileAction(
                        icon: Icons.comment, title: 'Комментарии'),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class ProfileInfoRow extends StatelessWidget {
  final IconData icon;
  final String title;
  final String value;
  const ProfileInfoRow({
    super.key,
    required this.icon,
    required this.title,
    required this.value,
  });

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 7),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon, color: moBlueDark, size: 20),
          const SizedBox(width: 9),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title,
                    style: const TextStyle(
                        color: moBlueDark, fontWeight: FontWeight.bold)),
                Text(value, style: const TextStyle(color: Colors.black87)),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _ProfileAction extends StatelessWidget {
  final IconData icon;
  final String title;
  const _ProfileAction({required this.icon, required this.title});

  @override
  Widget build(BuildContext context) {
    return Container(
      margin: const EdgeInsets.only(top: 5),
      color: Colors.white.withValues(alpha: 0.92),
      child: ListTile(
        leading: Icon(icon, color: moBlueDark),
        title: Text(title, style: const TextStyle(color: moBlueDark)),
        trailing: const Icon(Icons.chevron_right, color: Colors.grey),
        onTap: () => showMessage(context, 'Раздел «$title» будет добавлен позже'),
      ),
    );
  }
}

void showMessage(BuildContext context, String message) {
  ScaffoldMessenger.of(context).showSnackBar(
    SnackBar(content: Text(message), duration: const Duration(seconds: 2)),
  );
}
